select count(*) from location_trust_fix
where member_id = #{memberId} and received_at >= #{since}
  and lat = #{lat} and lng = #{lng}
  and accuracy_m = #{accuracy}accuracy_m is null

select lat, lng, received_at as receivedAt from location_trust_fix
where member_id = #{memberId} and received_at >= #{since}
  and decision = 'ACCEPT' and (simulated is null or simulated = 0)
order by id desc
limit #{limit}

select * from location_trust_fix
where (decision <> 'ACCEPT' or reasons is not null)
 and member_id = #{memberId}
 and kind = #{kind}
order by id desc
limit #{limit}

